-- Init schema and seed data for Tasks on MySQL 5.7
-- Generated from provided MySQL 8.0 dump, adjusted for 5.7 collations/order

SET NAMES utf8mb4;
SET time_zone = '+00:00';
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS `Tasks` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `Tasks`;

-- Users table must be created before user_sessions (FK dependency)
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `user_id` varchar(64) NOT NULL COMMENT '用户唯一ID（UUID）',
  `username` varchar(64) NOT NULL COMMENT '用户名',
  `email` varchar(128) NOT NULL COMMENT '邮箱',
  `role` varchar(16) NOT NULL DEFAULT 'user',
  `token_count` int NOT NULL DEFAULT '0',
  `password_hash` varchar(128) NOT NULL COMMENT '密码哈希（SHA256 十六进制）',
  `password_salt` varchar(64) NOT NULL COMMENT '盐（十六进制）',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1-正常 0-禁用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_id` (`user_id`),
  UNIQUE KEY `uk_username` (`username`),
  UNIQUE KEY `uk_email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='用户表';

LOCK TABLES `users` WRITE;
